void dei_temp_wake ( Wake_Status wake_status )
{    
	if( wake_status == s_WAKE )
	{
		dei_temp_vars.timeout_request = 1 ;
        
        vrtc_stop( dei_temp_vars.timeout_sensor_update ); 
	}
    else
    {
        vrtc_update( dei_temp_vars.timeout_sensor_update , DEI_TEMP_TIMEOUT_WAKE );
        vrtc_start ( dei_temp_vars.timeout_sensor_update );
    }		
} 

